  $healthDb=db();$runtime=$healthDb->query('SELECT VERSION() AS server_version,CURRENT_USER() AS db_account,DATABASE() AS db_name')->fetch();$dbConfig=require __DIR__.'/../config.php';
  $schemaText=@file_get_contents(__DIR__.'/../database/schema.sql');$expectedTables=[];if(is_string($schemaText))preg_match_all('/CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+`?([A-Za-z0-9_]+)`?/i',$schemaText,$tableMatches);$expectedTables=array_values(array_unique($tableMatches[1]??[]));
  $actualTables=array_map('strtolower',$healthDb->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE'")->fetchAll(PDO::FETCH_COLUMN));$missingTables=array_values(array_filter($expectedTables,static fn(string $name):bool=>!in_array(strtolower($name),$actualTables,true)));
  $nonInnoDb=(int)$healthDb->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' AND ENGINE<>'InnoDB'")->fetchColumn();
  $lastBackup=$healthDb->query("SELECT a.created_at,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.action='system.database_backup_requested' ORDER BY a.id DESC LIMIT 1")->fetch()?:null;
  $schoolConfigured=trim((string)($school['school_name']??''))!=='';$actualDbUser=strtolower(strtok((string)$runtime['db_account'],'@'));$passwordConfigured=(string)$dbConfig['password']!=='';$secureRequest=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';
  $healthChecks=[
    ['Database schema',!$missingTables&&count($expectedTables)>0?'Ready':'Action needed',!$missingTables&&count($expectedTables)>0?'All '.count($expectedTables).' tables from database/schema.sql are installed.':($missingTables?'Missing tables: '.implode(', ',$missingTables):'Could not read the schema table list.')],
    ['Transactional storage',$nonInnoDb===0?'Ready':'Action needed',$nonInnoDb===0?'All database tables use InnoDB.':$nonInnoDb.' table(s) are not InnoDB.'],
    ['Database login',($actualDbUser!=='root'&&$passwordConfigured)?'Review':'Action needed','Connected as '.$runtime['db_account'].'. '.($actualDbUser==='root'?'Use a dedicated non-root account. ':'').(!$passwordConfigured?'Configure a strong database password.':'A password is configured; verify the account has only required database privileges.')],
    ['Database permissions','Review','Confirm the application account cannot access other school databases and remove schema-changing privileges after migrations.'],
    ['Application mode',production_mode()?'Ready':'Action needed',production_mode()?'Production mode is enabled.':'Set SCHOOL_APP_ENV=production before deployment.'],
    ['HTTPS', $secureRequest?'Ready':'Action needed',$secureRequest?'This request uses HTTPS.':'Configure HTTPS before using real learner or guardian data.'],
    ['School profile',$schoolConfigured?'Review':'Action needed',$schoolConfigured?'School name is “'.(string)$school['school_name'].'”. Confirm the school code, contacts and address are correct.':'Enter the school’s own profile details.'],
    ['Backup storage','Review',$lastBackup?'Last backup request: '.date('d M Y H:i',strtotime($lastBackup['created_at'])).' by '.($lastBackup['full_name']??'former staff').'. Verify the file was saved in protected off-device storage.':'No database backup request is recorded yet. Download and store a protected off-device copy.'],
    ['Privacy and retention','Review','Set the school privacy notice, confirm the lawful basis and guardian authority, and define access and retention procedures for learner records.'],
  ];
  ?>
  <section class="panel settings-panel"><h2>Deployment readiness</h2><p>Checks the live database and request settings. Items marked Review need a school administrator or database administrator to confirm them.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Check</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach($healthChecks as $check): $badge=$check[1]==='Ready'?'granted':($check[1]==='Action needed'?'revoked':''); ?><tr><td><b><?= h($check[0]) ?></b></td><td><span class="consent-pill <?= h($badge) ?>"><?= h($check[1]) ?></span></td><td><?= h($check[2]) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="privacy-note">Database: <?= h($runtime['db_name']) ?> · <?= h($runtime['server_version']) ?>. This checklist is advisory; it does not replace a security review, verified backups, or Zimbabwean data-protection compliance work.</p></section>
